// sitemap.xml, generated by Next at /sitemap.xml.
//
// Only the pages a stranger has any reason to land on. A sitemap is a statement about what
// matters on a site, so padding it with the login form and every auth dead end makes the
// one page that does matter harder to find, not easier.
//
// lastModified is the build time rather than a hardcoded date. The copy on the landing page
// is generated from lib/personality.js, so it genuinely does change whenever the app is
// redeployed with different type taglines, and a stale date would be a lie.

export default function sitemap() {
  const site = process.env.NEXT_PUBLIC_SITE_URL || "https://vaeonfitness.com";
  const now = new Date();

  return [
    { url: site + "/", lastModified: now, changeFrequency: "weekly", priority: 1 },
    { url: site + "/signup", lastModified: now, changeFrequency: "yearly", priority: 0.5 },
    { url: site + "/disclaimer", lastModified: now, changeFrequency: "yearly", priority: 0.3 },
  ];
}
